/**
 * LibreOffice fixture tooling (test-time only). Each call uses a fresh profile.
 * Password-protected files are produced by LibreOffice itself through a Basic
 * macro installed in that throwaway profile (storeToURL with a Password).
 */
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { run } from '../../../src/lib/server/parsers/exec';
import { withTmp } from './helpers';

const env = (dir: string) => ({ PATH: process.env.PATH, HOME: dir, LANG: 'C.UTF-8' });

export async function sofficeAvailable(): Promise<boolean> {
	try {
		return (await run('soffice', ['--version'], { timeoutMs: 30_000 })).code === 0;
	} catch {
		return false;
	}
}

/** `soffice --headless --convert-to <to>` on generated bytes. */
export async function loConvert(bytes: Buffer, fromExt: string, to: string, infilter?: string): Promise<Buffer> {
	return withTmp(async (dir) => {
		const inPath = path.join(dir, `in.${fromExt}`);
		await writeFile(inPath, bytes);
		const out = path.join(dir, 'out');
		const r = await run(
			'soffice',
			[
				`-env:UserInstallation=file://${dir}/profile`,
				'--headless',
				'--norestore',
				...(infilter ? [`--infilter=${infilter}`] : []),
				'--convert-to',
				to,
				'--outdir',
				out,
				inPath
			],
			{ timeoutMs: 180_000, cwd: dir, env: env(dir) }
		);
		const ext = to.split(':')[0]!;
		const f = (await readdir(out).catch(() => [] as string[])).find((n) => n.endsWith(`.${ext}`));
		if (!f) throw new Error(`soffice convert ${fromExt}->${to} failed (${r.code}): ${r.stderr.slice(0, 400)}`);
		return readFile(path.join(out, f));
	});
}

const MODULE = `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE script:module PUBLIC "-//OpenOffice.org//DTD OfficeDocument 1.0//EN" "module.dtd">
<script:module xmlns:script="http://openoffice.org/2000/script" script:name="Module1" script:language="StarBasic">
Sub SaveAs(inUrl As String, outUrl As String, filterName As String, pw As String)
  Dim args(0) As New com.sun.star.beans.PropertyValue
  args(0).Name = &quot;Hidden&quot;
  args(0).Value = True
  doc = StarDesktop.loadComponentFromURL(inUrl, &quot;_blank&quot;, 0, args())
  Dim sargs(1) As New com.sun.star.beans.PropertyValue
  sargs(0).Name = &quot;FilterName&quot;
  sargs(0).Value = filterName
  If pw &lt;&gt; &quot;&quot; Then
    sargs(1).Name = &quot;Password&quot;
    sargs(1).Value = pw
  Else
    sargs(1).Name = &quot;Overwrite&quot;
    sargs(1).Value = True
  End If
  doc.storeToURL(outUrl, sargs())
  doc.close(True)
End Sub
</script:module>
`;

/**
 * Re-save a document through LibreOffice with an explicit filter and optional
 * open password (real encryption performed by LibreOffice).
 */
export async function loSaveAs(bytes: Buffer, fromExt: string, toExt: string, filterName: string, password: string): Promise<Buffer> {
	return withTmp(async (dir) => {
		const profile = path.join(dir, 'profile');
		const e = env(dir);
		await run('soffice', [`-env:UserInstallation=file://${profile}`, '--headless', '--norestore', '--terminate_after_init'], {
			timeoutMs: 120_000,
			cwd: dir,
			env: e
		});
		const std = path.join(profile, 'user', 'basic', 'Standard');
		await mkdir(std, { recursive: true });
		await writeFile(path.join(std, 'Module1.xba'), MODULE);
		const inPath = path.join(dir, `in.${fromExt}`);
		const outPath = path.join(dir, `out.${toExt}`);
		await writeFile(inPath, bytes);
		const url = `macro:///Standard.Module1.SaveAs("file://${inPath}","file://${outPath}","${filterName}","${password}")`;
		const r = await run('soffice', [`-env:UserInstallation=file://${profile}`, '--headless', '--norestore', url], {
			timeoutMs: 180_000,
			cwd: dir,
			env: e
		});
		try {
			return await readFile(outPath);
		} catch {
			throw new Error(`LibreOffice macro save failed (${r.code}): ${r.stderr.slice(0, 400)}`);
		}
	});
}
